using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedAstriumEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedAstrium Effect")]
public class CorruptedAstriumEffect : Effect
{
	[Header("Corrupted Astrium")]
	[SerializeField]
	private int amountToTriggerCorruptedAstrium;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private int corruptAmount;

	[SerializeField]
	private CorruptAction corruptAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return base.localizationManager.GetLocalizedWhenReachEffectActivateBaseFormatted(amountToTriggerCorruptedAstrium.ToString(), this, corruptAction.GetActionDescription(corruptAmount), amountToTriggerCorruptedAstrium.ToString());
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		EffectIncreased(effectAmount, effectOwner, source);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (effectAmount >= amountToTriggerCorruptedAstrium)
		{
			UnitEffects component = effectOwner.GetComponent<UnitEffects>();
			omenLogic.ActivateOmen(null, corruptAmount, null, null);
			component.IsEffectActive(this);
			component.IsEffectActiveRemoveEffect(this, activateFeedback: false);
			PlaySecondEffectActivationSFX();
			SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 3f);
		}
		else
		{
			PlayEffectActivationSFX();
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 3f);
		}
	}
}
